contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function
    function run(uint depositAmt, uint collectAmt) public payable {
        require(address(this).balance >= depositAmt, "insufficient test balance for deposit");

        // ensure MinSum is zero so that Collect can succeed when balance>=collectAmt
        // SetMinSum can only be called before c.Initialized(); as tester we call it now
        c.SetMinSum(0);

        // record balances before interactions
        uint beforeCallerBalance = c.balances(address(this));
        uint beforeContractEth = address(c).balance;

        // make a deposit to c from this contract
        c.Deposit{value: depositAmt}();

        // record after-deposit values
        uint afterDepositCallerBalance = c.balances(address(this));
        uint afterDepositContractEth = address(c).balance;

        // try to Collect collectAmt and observe whether it reverted
        bool collectReverted;
        try c.Collect(collectAmt) {
            collectReverted = false;
        } catch {
            collectReverted = true;
        }

        // read final stored balance and contract ETH balance
        uint finalCallerBalance = c.balances(address(this));
        uint finalContractEth = address(c).balance;

        // General property:
        // If Collect succeeded (did not revert) then stored balance decreased by collectAmt
        // and contract's ETH decreased by collectAmt. If Collect reverted then stored balance
        // and contract ETH remain as after the deposit (no partial change).
        assert(
            (!collectReverted && afterDepositCallerBalance >= collectAmt &&
                finalCallerBalance + collectAmt == afterDepositCallerBalance &&
                finalContractEth + collectAmt == afterDepositContractEth)
            ||
            (collectReverted && finalCallerBalance == afterDepositCallerBalance && finalContractEth == afterDepositContractEth)
        );
    }

    // receive to accept refunds if any
    receive() external payable {}
}

