contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function
    function run(uint depositAmount, uint collectAmount) public payable {
        require(address(this).balance >= depositAmount);
        // ensure MinSum set low enough and Log set so contract can operate before initializing
        // Set MinSum and Log only allowed before Initialized, so call them now
        c.SetMinSum(0);
        c.SetLogFile(address(this));
        // Deposit some Ether into c from this contract
        c.Deposit{value: depositAmount}();

        // read balances before trying to collect
        uint beforeBal = c.balances(address(this));
        uint cBalBefore = address(c).balance;

        // attempt Collect and record whether it reverted
        bool reverted;
        try c.Collect(collectAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint afterBal = c.balances(address(this));
        uint cBalAfter = address(c).balance;

        // General rule: if Collect did not revert then the contract's recorded balance
        // for this caller decreased by exactly collectAmount and the contract's Ether
        // balance decreased by at least collectAmount (caller may fail to receive Ether only by reverting,
        // so on success the contract balance must drop by >= collectAmount).
        assert(reverted || (beforeBal >= collectAmount && afterBal + collectAmount == beforeBal && cBalBefore >= cBalAfter && (cBalBefore - cBalAfter) >= collectAmount));
    }

    // receive to accept refunds if any (not strictly needed)
    receive() external payable {}
}

